pub fn parse_size(s: &str) -> Option<u64> {
    let s = trim_ascii(s);
    if s.is_empty() {
        return None;
    }

    let bytes = s.as_bytes();
    let mut end = 0;
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
    }
    if end == 0 {
        return None;
    }

    let digits = &s[..end];
    let value: u64 = digits.parse().ok()?;

    let rest = trim_ascii(&s[end..]);
    if rest.is_empty() {
        return Some(value);
    }

    if rest.as_bytes().iter().any(|b| b.is_ascii_whitespace()) {
        return None;
    }

    let multiplier = unit_multiplier(rest)?;
    value.checked_mul(multiplier)
}

pub fn trim_ascii(s: &str) -> &str {
    let start = s
        .char_indices()
        .find(|(_, c)| !c.is_ascii_whitespace())
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    let end = s
        .char_indices()
        .rev()
        .find(|(_, c)| !c.is_ascii_whitespace())
        .map(|(i, c)| i + c.len_utf8())
        .unwrap_or(start);
    &s[start..end]
}

pub fn unit_multiplier(unit: &str) -> Option<u64> {
    match unit.to_ascii_lowercase().as_str() {
        "" | "b" => Some(1),
        "kib" => Some(1024),
        "mib" => Some(1024u64.pow(2)),
        "gib" => Some(1024u64.pow(3)),
        "tib" => Some(1024u64.pow(4)),
        "kb" => Some(1000),
        "mb" => Some(1000u64.pow(2)),
        "gb" => Some(1000u64.pow(3)),
        "tb" => Some(1000u64.pow(4)),
        _ => None,
    }
}
