/// Parses a comma-separated list of non-negative integers and inclusive ranges.
///
/// `"1-3, 5,7-8"` -> `Some([1, 2, 3, 5, 7, 8])`; order preserved, no dedup.
pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    let trimmed = s.trim_matches(|c: char| c.is_ascii_whitespace());
    if trimmed.is_empty() {
        return Some(Vec::new());
    }

    let mut out: Vec<u32> = Vec::new();

    for item in trimmed.split(',') {
        let item = item.trim_matches(|c: char| c.is_ascii_whitespace());
        if item.is_empty() {
            return None;
        }

        match item.split_once('-') {
            Some((lo, hi)) => {
                let lo = parse_nonneg_u32(lo)?;
                let hi = parse_nonneg_u32(hi)?;
                if lo > hi {
                    return None;
                }
                out.extend(lo..=hi);
            }
            None => out.push(parse_nonneg_u32(item)?),
        }
    }

    Some(out)
}

/// Parses one non-negative decimal integer, ignoring surrounding ASCII whitespace.
/// Rejects an empty string, any non-digit character (including `+`, `-`, spaces
/// embedded in the number) and values that do not fit in `u32`.
pub fn parse_nonneg_u32(s: &str) -> Option<u32> {
    let s = s.trim_matches(|c: char| c.is_ascii_whitespace());
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse::<u32>().ok()
}
