pub fn parse_size(s: &str) -> Option<u64> {
    let trimmed = s.trim_matches(char::is_ascii_whitespace);

    let digit_count = trimmed
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .count();
    if digit_count == 0 {
        return None;
    }

    let (digits, rest) = trimmed.split_at(digit_count);
    let value = digits.parse::<u64>().ok()?;

    let rest = rest.trim_start_matches(char::is_ascii_whitespace);
    if rest.is_empty() {
        return Some(value);
    }

    let (unit, trailing) = match rest.find(char::is_ascii_whitespace) {
        Some(i) => rest.split_at(i),
        None => (rest, ""),
    };
    if !trailing.trim_matches(char::is_ascii_whitespace).is_empty() {
        return None;
    }

    let multiplier: u64 = if unit.eq_ignore_ascii_case("B") {
        1
    } else if unit.eq_ignore_ascii_case("KiB") {
        1024
    } else if unit.eq_ignore_ascii_case("MiB") {
        1024u64.pow(2)
    } else if unit.eq_ignore_ascii_case("GiB") {
        1024u64.pow(3)
    } else if unit.eq_ignore_ascii_case("TiB") {
        1024u64.pow(4)
    } else if unit.eq_ignore_ascii_case("KB") {
        1000
    } else if unit.eq_ignore_ascii_case("MB") {
        1000u64.pow(2)
    } else if unit.eq_ignore_ascii_case("GB") {
        1000u64.pow(3)
    } else if unit.eq_ignore_ascii_case("TB") {
        1000u64.pow(4)
    } else {
        return None;
    };

    value.checked_mul(multiplier)
}
