pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    let is_ws = |c: char| c.is_ascii_whitespace();

    let trimmed_all = s.trim_matches(is_ws);
    if trimmed_all.is_empty() {
        return Some(Vec::new());
    }

    let mut out = Vec::new();

    for item in trimmed_all.split(',') {
        let item = item.trim_matches(is_ws);

        if item.is_empty() {
            return None;
        }

        if let Some((left, right)) = item.split_once('-') {
            let left = left.trim_matches(is_ws);
            let right = right.trim_matches(is_ws);

            if left.is_empty() || right.is_empty() {
                return None;
            }

            let start: u32 = left.parse().ok()?;
            let end: u32 = right.parse().ok()?;

            if start > end {
                return None;
            }

            out.push(start);
            let mut current = start;
            while current < end {
                current += 1;
                out.push(current);
            }
        } else {
            let value: u32 = item.parse().ok()?;
            out.push(value);
        }
    }

    Some(out)
}
