pub fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim_matches(|c: char| c.is_ascii_whitespace());

    let digits_len = s
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(s.len());
    if digits_len == 0 {
        return None;
    }

    let (digits, rest) = s.split_at(digits_len);
    let value: u64 = digits.parse().ok()?;

    let suffix = rest.trim_start_matches(|c: char| c.is_ascii_whitespace());

    let multiplier: u64 = if suffix.is_empty() || suffix.eq_ignore_ascii_case("b") {
        1
    } else if suffix.eq_ignore_ascii_case("kib") {
        1024
    } else if suffix.eq_ignore_ascii_case("mib") {
        1024 * 1024
    } else if suffix.eq_ignore_ascii_case("gib") {
        1024 * 1024 * 1024
    } else if suffix.eq_ignore_ascii_case("tib") {
        1024 * 1024 * 1024 * 1024
    } else if suffix.eq_ignore_ascii_case("kb") {
        1000
    } else if suffix.eq_ignore_ascii_case("mb") {
        1000 * 1000
    } else if suffix.eq_ignore_ascii_case("gb") {
        1000 * 1000 * 1000
    } else if suffix.eq_ignore_ascii_case("tb") {
        1000 * 1000 * 1000 * 1000
    } else {
        return None;
    };

    value.checked_mul(multiplier)
