pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    let trimmed = s.trim_matches(|c: char| c.is_ascii_whitespace());
    if trimmed.is_empty() {
        return Some(Vec::new());
    }

    let mut out = Vec::new();
    for item in trimmed.split(',') {
        let item = item.trim_matches(|c: char| c.is_ascii_whitespace());
        if item.is_empty() {
            return None;
        }

        let parts: Vec<&str> = item.split('-').collect();
        match parts.len() {
            1 => {
                out.push(parse_number(parts[0])?);
            }
            2 => {
                let start = parse_number(parts[0])?;
                let end = parse_number(parts[1])?;
                if start > end {
                    return None;
                }
                let mut v = start;
                loop {
                    out.push(v);
                    if v == end {
                        break;
                    }
                    v += 1;
                }
            }
            _ => return None,
        }
    }

    Some(out)
}

