pub fn trim_ascii_whitespace(s: &str) -> &str {
    match s
        .char_indices()
        .find(|(_, c)| !c.is_ascii_whitespace())
    {
        None => "",
        Some((start, _)) => {
            let end = s
                .char_indices()
                .rev()
                .find(|(_, c)| !c.is_ascii_whitespace())
                .map_or(start, |(i, c)| i + c.len_utf8());
            &s[start..end]
        }
    }
}

