    for item in s.split(',') {
        let item = trim_ascii_whitespace(item);
        if item.is_empty() {
            return None;
        }

        match item.find('-') {
            None => {
                out.push(parse_u32_strict(item)?);
            }
            Some(i) => {
                let lo = parse_u32_strict(trim_ascii_whitespace(&item[..i]))?;
                let hi = parse_u32_strict(trim_ascii_whitespace(&item[i + 1..]))?;
                if lo > hi {
                    return None;
                }
                out.extend(lo..=hi);
            }
        }
    }

    Some(out)
