pub struct LruCache {
    capacity: usize,
    entries: Vec<(u64, String)>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            entries: Vec::new(),
        }
    }

    pub fn get(&mut self, key: u64) -> Option<String> {
        if self.capacity == 0 {
            return None;
        }

        let index = self.entries.iter().position(|(entry_key, _)| *entry_key == key)?;

        let value = self.entries[index].1.clone();
        let entry = self.entries.remove(index);
        self.entries.push(entry);

        Some(value)
    }

    pub fn put(&mut self, key: u64, value: String) {
        if self.capacity == 0 {
            return;
        }

        if let Some(index) = self.entries.iter().position(|(entry_key, _)| *entry_key == key) {
            self.entries[index].1 = value;
            let entry = self.entries.remove(index);
            self.entries.push(entry);
            return;
        }

        if self.entries.len() >= self.capacity {
            self.entries.remove(0);
        }

        self.entries.push((key, value));
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
}
