        let parts: Vec<&str> = item.split('-').collect();
        match parts.len() {
            1 => {
                out.push(parse_u32(parts[0])?);
            }
            2 => {
                let start = parse_u32(parts[0])?;
                let end = parse_u32(parts[1])?;
                if start > end {
                    return None;
                }
                let mut n = start;
                loop {
                    out.push(n);
                    if n == end {
                        break;
                    }
                    n += 1;
                }
            }
            _ => return None,
        }
    }

    Some(out)
}

