            let (a_s, b_s) = match (it.next(), it.next()) {
                (Some(a), Some(b)) => (a, b),
                _ => return None,
            };
            if it.next().is_some() {
                return None;
            }

            let a = parse_u32(trim_ascii(a_s))?;
            let b = parse_u32(trim_ascii(b_s))?;
            if a > b {
                return None;
            }
            for v in a..=b {
                out.push(v);
            }
        } else {
            out.push(parse_u32(t)?);
        }
    }

    Some(out)
}
