/// Parses a byte-size string such as `"4 KiB"` or `"1MB"` into a byte count.
///
/// Returns `None` for malformed input, an unknown suffix, or on overflow.
pub fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim_matches(|c: char| c.is_ascii_whitespace());

    let digits_end = s
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(s.len());
    let digits = &s[..digits_end];
    if digits.is_empty() {
        return None;
    }
    let value: u64 = digits.parse().ok()?;

    let rest = s[digits_end..]
        .trim_start_matches(|c: char| c.is_ascii_whitespace())
        .trim_end_matches(|c: char| c.is_ascii_whitespace());
    if rest.is_empty() {
        return Some(value);
    }

    let mult: u64 = if rest.eq_ignore_ascii_case("B") {
        1
    } else if rest.eq_ignore_ascii_case("KiB") {
        1024
    } else if rest.eq_ignore_ascii_case("MiB") {
        1024u64.pow(2)
    } else if rest.eq_ignore_ascii_case("GiB") {
        1024u64.pow(3)
    } else if rest.eq_ignore_ascii_case("TiB") {
        1024u64.pow(4)
    } else if rest.eq_ignore_ascii_case("KB") {
        1000
    } else if rest.eq_ignore_ascii_case("MB") {
        1000u64.pow(2)
    } else if rest.eq_ignore_ascii_case("GB") {
        1000u64.pow(3)
    } else if rest.eq_ignore_ascii_case("TB") {
        1000u64.pow(4)
    } else {
        return None;
    };

    value.checked_mul(mult)
}
