pub struct LruCache {
    pub capacity: usize,
    /// Storage order encodes recency: front is least-recently-used,
    /// back is most-recently-used.
    pub entries: Vec<(u64, String)>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        LruCache {
            capacity,
            entries: Vec::new(),
        }
    }

    pub fn get(&mut self, key: u64) -> Option<String> {
        let idx = match self.entries.iter().position(|(k, _)| *k == key) {
            Some(idx) => idx,
            None => return None, // miss: touch nothing
        };
        let entry = self.entries.remove(idx);
        let value = entry.1.clone();
        self.entries.push(entry); // now most-recently-used
        Some(value)
    }

    pub fn put(&mut self, key: u64, value: String) {
        if self.capacity == 0 {
            return;
        }
        if let Some(idx) = self.entries.iter().position(|(k, _)| *k == key) {
            // Overwrite: remove old slot so len() is unchanged after the push.
            self.entries.remove(idx);
        } else if self.entries.len() >= self.capacity {
            // New key at capacity: evict the least-recently-used entry.
            self.entries.remove(0);
        }
        self.entries.push((key, value));
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
}
