pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    let trim = |t: &str| t.trim_matches(|c: char| c.is_ascii_whitespace());

    if trim(s).is_empty() {
        return Some(Vec::new());
    }

    let number = |t: &str| -> Option<u32> {
        let t = trim(t);
        if t.is_empty() || !t.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        t.parse::<u32>().ok()
    };

    let mut out = Vec::new();

    for item in s.split(',') {
        let item = trim(item);
        if item.is_empty() {
            return None;
        }

        let (head, tail) = match item.find('-') {
            Some(pos) => (&item[..pos], Some(&item[pos + 1..])),
            None => (item, None),
        };

        let start = number(head)?;
        match tail {
            None => out.push(start),
            Some(tail) => {
                let end = number(tail)?;
                if start > end {
                    return None;
                }
                out.extend(start..=end);
            }
        }
    }

    Some(out)
}
