/// Parses a byte-size string like "512", "4KiB" or "  4kib  " into a number of bytes.
///
/// Returns `None` for empty/whitespace-only input, missing digits, signs,
/// decimal points, unknown suffixes, trailing junk, or overflow in either
/// the integer parse or the unit multiplication.
pub fn parse_size(s: &str) -> Option<u64> {
    let bytes = s.as_bytes();

    let mut i = 0;
    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }

    let digits_start = i;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
    }
    if i == digits_start {
        return None;
    }

    let digits = std::str::from_utf8(&bytes[digits_start..i]).ok()?;
    let value: u64 = digits.parse().ok()?;

    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }
    let mut end = bytes.len();
    while end > i && bytes[end - 1].is_ascii_whitespace() {
        end -= 1;
    }

    let suffix = &bytes[i..end];
    if suffix.is_empty() {
        return Some(value);
    }

    let multiplier = unit_multiplier(suffix)?;
    value.checked_mul(multiplier)
}

/// Returns the multiplier for a non-empty unit suffix, matched case-insensitively.
pub fn unit_multiplier(suffix: &[u8]) -> Option<u64> {
    let lower = suffix.to_ascii_lowercase();
    let multiplier: u64 = match lower.as_slice() {
        b"b" => 1,
        b"kib" => 1 << 10,
        b"mib" => 1 << 20,
        b"gib" => 1 << 30,
        b"tib" => 1 << 40,
        b"kb" => 1_000,
        b"mb" => 1_000_000,
        b"gb" => 1_000_000_000,
        b"tb" => 1_000_000_000_000,
        _ => return None,
    };
    Some(multiplier)
}
