pub struct LruCache {
    pub capacity: usize,
    pub entries: std::collections::HashMap<u64, String>,
    pub recency: std::collections::VecDeque<u64>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        LruCache {
            capacity,
            entries: std::collections::HashMap::new(),
            recency: std::collections::VecDeque::new(),
        }
    }

    pub fn get(&mut self, key: u64) -> Option<String> {
        if self.entries.contains_key(&key) {
            let value = self.entries[&key].clone();
            self.recency.retain(|&mut k| k != key);
            self.recency.push_back(key);
            Some(value)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: u64, value: String) {
        if self.capacity == 0 {
            return;
        }

        if self.entries.contains_key(&key) {
            self.entries.insert(key, value);
            self.recency.retain(|&mut k| k != key);
            self.recency.push_back(key);
            return;
        }

        if self.entries.len() >= self.capacity {
            if let Some(evicted_key) = self.recency.pop_front() {
                self.entries.remove(&evicted_key);
            }
        }

        self.entries.insert(key, value);
        self.recency.push_back(key);
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }
}
