pub fn parse_size(s: &str) -> Option<u64> {
    let s = trim_ascii(s);
    if s.is_empty() {
        return None;
    }

    let mut end = 0usize;
    for b in s.as_bytes() {
        if b.is_ascii_digit() {
            end += 1;
        } else {
            break;
        }
    }
    if end == 0 {
        return None;
    }

    let digits = &s[..end];
    let suffix = trim_ascii(&s[end..]);
    if suffix.chars().any(|c| c.is_ascii_whitespace()) {
        return None;
    }

    let value: u64 = digits.parse().ok()?;
    let multiplier = size_multiplier(suffix)?;
    value.checked_mul(multiplier)
}

pub fn size_multiplier(suffix: &str) -> Option<u64> {
    const K: u64 = 1024;
    const D: u64 = 1000;

    match suffix.to_ascii_uppercase().as_str() {
        "" | "B" => Some(1),
        "KIB" => Some(K),
        "MIB" => Some(K * K),
        "GIB" => Some(K * K * K),
        "TIB" => Some(K * K * K * K),
        "KB" => Some(D),
        "MB" => Some(D * D),
        "GB" => Some(D * D * D),
        "TB" => Some(D * D * D * D),
        _ => None,
    }
}

pub fn trim_ascii(s: &str) -> &str {
    s.trim_matches(|c: char| c.is_ascii_whitespace())
}
