pub fn parse_range_list_ascii_trim(s: &str) -> &str {
    let is_ascii_whitespace = |b: u8| {
        matches!(
            b,
            b' ' | b'\t' | b'\n' | b'\r' | b'\x0B' | b'\x0C'
        )
    };

    let bytes = s.as_bytes();
    let mut start = 0;
    let mut end = bytes.len();

    while start < end && is_ascii_whitespace(bytes[start]) {
        start += 1;
    }

    while end > start && is_ascii_whitespace(bytes[end - 1]) {
        end -= 1;
    }

    &s[start..end]
