pub fn parse_range_list(s: &str) -> Option<Vec<u32>> {
    if s.bytes().all(|b| b.is_ascii_whitespace()) {
        return Some(vec![]);
    }

    let mut out = Vec::new();

    for item in s.split(',') {
        let item = trim_ascii_whitespace(item);
        if item.is_empty() {
            return None;
        }

        if let Some((left, right)) = item.split_once('-') {
            if right.contains('-') {
                return None;
            }

            let start = parse_u32(left)?;
            let end = parse_u32(right)?;

            if start > end {
                return None;
            }

            out.extend(start..=end);
        } else {
            out.push(parse_u32(item)?);
        }
    }

    Some(out)
}

pub fn trim_ascii_whitespace(s: &str) -> &str {
    let bytes = s.as_bytes();
    let mut start = 0;
    let mut end = bytes.len();

    while start < end && bytes[start].is_ascii_whitespace() {
        start += 1;
    }

    while end > start && bytes[end - 1].is_ascii_whitespace() {
        end -= 1;
    }

    &s[start..end]
}

pub fn parse_u32(s: &str) -> Option<u32> {
    let s = trim_ascii_whitespace(s);
    if s.is_empty() {
        return None;
    }

    let mut value: u32 = 0;

    for b in s.as_bytes() {
        if !b.is_ascii_digit() {
            return None;
        }

        value = value
            .checked_mul(10)?
            .checked_add(u32::from(b - b'0'))?;
    }

    Some(value)
}
