pub fn parse_size(s: &str) -> Option<u64> {
    let bytes = s.as_bytes();
    let mut pos = 0usize;

    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }

    let digits_start = pos;
    let mut value: u64 = 0;

    while pos < bytes.len() && bytes[pos].is_ascii_digit() {
        let digit = (bytes[pos] - b'0') as u64;
        value = value.checked_mul(10)?.checked_add(digit)?;
        pos += 1;
    }

    if pos == digits_start {
        return None;
    }

    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }

    if pos == bytes.len() {
        return Some(value);
    }

    let suffix_start = pos;
    let mut suffix: [u8; 8] = [0u8; 8];
    let mut len = 0usize;

    while pos < bytes.len() && bytes[pos].is_ascii_alphabetic() {
        if len == suffix.len() {
            return None;
        }
        suffix[len] = bytes[pos].to_ascii_uppercase();
        len += 1;
        pos += 1;
    }

    if pos == suffix_start {
        return None;
    }

    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }

    if pos != bytes.len() {
        return None;
    }

    let suffix = &suffix[..len];
    let multiplier: u64 = match suffix {
        [b'B'] => 1,
        [b'K', b'I', b'B'] => 1024,
        [b'M', b'I', b'B'] => 1024 * 1024,
        [b'G', b'I', b'B'] => 1024 * 1024 * 1024,
        [b'T', b'I', b'B'] => 1024 * 1024 * 1024 * 1024,
        [b'K', b'B'] => 1000,
        [b'M', b'B'] => 1000 * 1000,
        [b'G', b'B'] => 1000 * 1000 * 1000,
        [b'T', b'B'] => 1000 * 1000 * 1000 * 1000,
        _ => return None,
    };

    value.checked_mul(multiplier)
