pub struct LruCache {
    capacity: usize,
    map: std::collections::HashMap<u64, usize>,
    keys: Vec<u64>,
    values: Vec<String>,
    prev: Vec<Option<usize>>,
    next: Vec<Option<usize>>,
    head: Option<usize>,
    tail: Option<usize>,
}

impl LruCache {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            map: std::collections::HashMap::new(),
            keys: Vec::new(),
            values: Vec::new(),
            prev: Vec::new(),
            next: Vec::new(),
            head: None,
            tail: None,
        }
    }

    pub fn get(&mut self, key: u64) -> Option<String> {
        let idx = match self.map.get(&key) {
            Some(&idx) => idx,
            None => return None,
        };

        if self.head != Some(idx) {
            let prev = self.prev[idx];
            let next = self.next[idx];

            if let Some(p) = prev {
                self.next[p] = next;
            } else {
                self.head = next;
            }

            if let Some(n) = next {
                self.prev[n] = prev;
            } else {
                self.tail = prev;
            }

            self.prev[idx] = None;
            self.next[idx] = self.head;

            if let Some(h) = self.head {
                self.prev[h] = Some(idx);
            }

            self.head = Some(idx);

            if self.tail.is_none() {
                self.tail = Some(idx);
            }
        }

        Some(self.values[idx].clone())
    }

    pub fn put(&mut self, key: u64, value: String) {
        if self.capacity == 0 {
            return;
        }

        if let Some(&idx) = self.map.get(&key) {
            self.values[idx] = value;

            if self.head != Some(idx) {
                let prev = self.prev[idx];
                let next = self.next[idx];

                if let Some(p) = prev {
                    self.next[p] = next;
                } else {
                    self.head = next;
                }

                if let Some(n) = next {
                    self.prev[n] = prev;
                } else {
                    self.tail = prev;
                }

                self.prev[idx] = None;
                self.next[idx] = self.head;

                if let Some(h) = self.head {
                    self.prev[h] = Some(idx);
                }

                self.head = Some(idx);

                if self.tail.is_none() {
                    self.tail = Some(idx);
                }
            }

            return;
        }

        if self.len() >= self.capacity {
            let idx = match self.tail {
                Some(idx) => idx,
                None => return,
            };

            let evicted_key = self.keys[idx];
            self.map.remove(&evicted_key);

            let prev = self.prev[idx];

            if let Some(p) = prev {
                self.next[p] = None;
                self.tail = Some(p);
            } else {
                self.head = None;
                self.tail = None;
            }

            self.prev[idx] = None;
            self.next[idx] = None;

            self.keys[idx] = key;
            self.values[idx] = value;

            self.next[idx] = self.head;

            if let Some(h) = self.head {
                self.prev[h] = Some(idx);
            }

            self.head = Some(idx);

            if self.tail.is_none() {
                self.tail = Some(idx);
            }

            self.map.insert(key, idx);
            return;
        }

        let idx = self.keys.len();

        self.keys.push(key);
        self.values.push(value);
        self.prev.push(None);
        self.next.push(self.head);

        if let Some(h) = self.head {
            self.prev[h] = Some(idx);
        }

        self.head = Some(idx);

        if self.tail.is_none() {
            self.tail = Some(idx);
        }

        self.map.insert(key, idx);
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }
}
