            order: Vec::new(),
        }
    }

    pub fn get(&mut self, key: u64) -> Option<String> {
        if self.capacity == 0 {
            return None;
        }

        if let Some(value) = self.map.get(&key).cloned() {
            self.order.retain(|&existing| existing != key);
            self.order.push(key);
            Some(value)
        } else {
            None
        }
    }

    pub fn put(&mut self, key: u64, value: String) {
        if self.capacity == 0 {
            return;
        }

        if self.map.contains_key(&key) {
            self.map.insert(key, value);
            self.order.retain(|&existing| existing != key);
            self.order.push(key);
            return;
        }

        if self.map.len() >= self.capacity {
            if let Some(old) = self.order.first().copied() {
                self.map.remove(&old);
                self.order.remove(0);
            }
        }

        self.map.insert(key, value);
        self.order.push(key);
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }
