    }

    let c0 = bytes[i].to_ascii_uppercase();
    let suffix: Option<(usize, u64)> = if c0 == b'B' {
        Some((1, 1))
    } else if n - i >= 3
        && bytes[i + 1].to_ascii_uppercase() == b'I'
        && bytes[i + 2].to_ascii_uppercase() == b'B'
    {
        match c0 {
            b'K' => Some((3, 1024)),
            b'M' => Some((3, 1_048_576)),
            b'G' => Some((3, 1_073_741_824)),
            b'T' => Some((3, 1_099_511_627_776)),
            _ => None,
        }
    } else if n - i >= 2 && bytes[i + 1].to_ascii_uppercase() == b'B' {
        match c0 {
            b'K' => Some((2, 1000)),
            b'M' => Some((2, 1_000_000)),
            b'G' => Some((2, 1_000_000_000)),
            b'T' => Some((2, 1_000_000_000_000)),
            _ => None,
        }
    } else {
        None
    };

    if let Some((len, multiplier)) = suffix {
        i += len;
        while i < n && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i == n {
            value.checked_mul(multiplier)
        } else {
            None
        }
    } else {
        None
    }
}
